Definition": "Purchases at least once per week"}, {"name": "中頻", "value": "MEDIUM", "semanticDefinition": "Purchases 2-4 times per month"}, {"name": "低頻", "value": "LOW", "semanticDefinition": "Purchases less than twice per month"}, {"name": "沉睡", "value": "DORMANT", "semanticDefinition": "No purchase in last 90 days"}]}, {"attribute": "archetype", "type": "quiz", "sources": [], "sql": null, "quiz": {"questions": [{"id": "q1", "text": "When faced with a new challenge, you prefer to:", "options": [{"id": "a", "text": "Explore all possibilities before deciding", "mappings": {"explorer": 2, "sage": 1}}, {"id": "b", "text": "Take decisive action immediately", "mappings": {"hero": 2, "rebel": 1}}, {"id": "c", "text": "Research thoroughly and plan ahead", "mappings": {"sage": 2, "ruler": 1}}, {"id": "d", "text": "Find a creative unconventional solution", "mappings": {"creator": 2, "magician": 1}}]}, {"id": "q2", "text": "In social situations, you tend to:", "options": [{"id": "a", "text": "Share stories and make people laugh", "mappings": {"jester": 2, "explorer": 1}}, {"id": "b", "text": "Listen carefully and offer support", "mappings": {"caregiver": 2, "innocent": 1}}, {"id": "c", "text": "Take charge and organize the group", "mappings": {"ruler": 2, "hero": 1}}, {"id": "d", "text": "Connect deeply with individuals", "mappings": {"lover": 2, "everyman": 1}}]}, {"id": "q3", "text": "Your ideal weekend activity would be:", "options": [{"id": "a", "text": "Discovering a new hiking trail or travel destination", "mappings": {"explorer": 2, "innocent": 1}}, {"id": "b", "text": "Working on a personal creative project", "mappings": {"creator": 2, "magician": 1}}, {"id": "c", "text": "Volunteering or helping friends", "mappings": {"caregiver": 2, "everyman": 1}}, {"id": "d", "text": "Attending a protest or community event", "mappings": {"rebel": 2, "hero": 1}}]}, {"id": "q4", "text": "When shopping, what matters most to you?", "options": [{"id": "a", "text": "Quality and timeless design", "mappings": {"ruler": 2, "sage": 1}}, {"id": "b", "text": "Unique or limited-edition items", "mappings": {"creator": 2, "rebel": 1}}, {"id": "c", "text": "Great value and popular brands", "mappings": {"everyman": 2, "innocent": 1}}, {"id": "d", "text": "Sensory experience — texture, scent, aesthetics", "mappings": {"lover": 2, "magician": 1}}]}, {"id": "q5", "text": "Which statement resonates with you the most?", "options": [{"id": "a", "text": "Life is an adventure to be lived fully", "mappings": {"explorer": 2, "jester": 1}}, {"id": "b", "text": "Knowledge is the key to everything", "mappings": {"sage": 2, "creator": 1}}, {"id": "c", "text": "The world needs more kindness and care", "mappings": {"caregiver": 2, "innocent": 1}}, {"id": "d", "text": "Rules are meant to be questioned", "mappings": {"rebel": 2, "magician": 1}}]}], "scoring": {"primaryThreshold": 3, "secondaryThreshold": 2, "maxPrimary": 1, "maxSecondary": 2}}, "valueMappings": []}]}$json$::jsonb, '1.0.0'
FROM sites s WHERE s.slug = 'default'
ON CONFLICT (site_id, config_type) DO NOTHING;

